from pathlib import Path
import boto3,json
root=Path('tmp/registry-access-release');p=root/'release-state.json';state=json.loads(p.read_text());assert all(v['deploy_status']=='SUCCEEDED' for v in state['services'].values());s=boto3.Session(profile_name='rfone-dev-login',region_name='us-east-1');script=(root/'anthony_aws_update.py').read_text();r=s.client('ecs').run_task(cluster=state['verification_cluster'],taskDefinition=state['verification_task_definition'],launchType='FARGATE',networkConfiguration=state['verification_network'],overrides={'containerOverrides':[{'name':state['verification_container'],'command':['-c',script]}]},startedBy='rf1-anthony-kitchen-only');assert not r.get('failures'),r.get('failures');state['anthony_update_task']=r['tasks'][0]['taskArn'];p.write_text(json.dumps(state,indent=2));print('Anthony Kitchen-only update task started:',state['anthony_update_task'])
r=s.client('cloudfront').create_invalidation(DistributionId=state['cloudfront_distribution'],InvalidationBatch={'Paths':{'Quantity':1,'Items':['/*']},'CallerReference':'registry-access-'+state['commit']});state['cloudfront_invalidation']=r['Invalidation']['Id'];p.write_text(json.dumps(state,indent=2));print('RF1 cache invalidation:',state['cloudfront_invalidation'])
